mapper.select:
SELECT fact_value AS "factValue",
       state_version AS "stateVersion",
       observed_at AS "observedAt"
  FROM device_fact
 WHERE tenant_id = #{tenantId} AND device_resource_id = #{deviceResourceId}
   AND fact_type = #{factType}

mapper.update:
UPDATE device_fact
   SET observed_at = NULL, updated_at = now()
 WHERE tenant_id = #{tenantId} AND device_resource_id = #{deviceResourceId}
